export function alpha(value: number): number {
  const first = value * 2;
  const second = first + 1;
  const third = second * 3;
  const fourth = third + 4;
  const fifth = fourth * 5;
  return fifth;
}

export function beta(value: number): number {
  const first = value * 3;
  const second = first + 2;
  const third = second * 4;
  const fourth = third + 5;
  const fifth = fourth * 6;
  return fifth;
}
